<div class="container-fluid py-3"><div class="d-flex justify-content-between align-items-center mb-3"><div><h3 class="mb-1"><i class="bi bi-diagram-3 me-2"></i>Network Map</h3><small class="text-muted">Router and customer topology</small></div><span class="badge bg-success">{{ $routers->where('action','connected')->count() }} online / {{ $routers->where('action','!=','connected')->count() }} offline</span></div><div class="row g-3 mb-3"><div class="col-md-3"><div class="card"><div class="card-body"><small>Active Customers</small><h4>{{ number_format($customers) }}</h4></div></div></div><div class="col-md-3"><div class="card"><div class="card-body"><small>Map Nodes</small><h4>{{ number_format($nodes->count()) }}</h4></div></div></div><div class="col-md-6"><div class="card"><div class="card-body"><small>Connected Routers</small><div class="d-flex gap-2 flex-wrap mt-2">@forelse($routers as $r)<span class="badge {{ $r->action === 'connected' ? 'bg-success' : 'bg-secondary' }}">{{ $r->router_name }} · {{ $r->action === 'connected' ? 'Online' : 'Offline' }}</span>@empty<span class="text-muted">No connected routers</span>@endforelse</div></div></div></div></div><div class="card"><div class="card-body"><div class="row g-2 mb-3"><div class="col-md-4"><label class="form-label">Router</label><select id="map-router-filter" class="form-select"><option value="">All Routers</option>@foreach($routers as $r)<option value="{{ $r->router_name }}">{{ $r->router_name }}</option>@endforeach</select></div><div class="col-md-4"><label class="form-label">Customer Status</label><select id="map-status-filter" class="form-select"><option value="">All Status</option><option value="online">Online</option><option value="offline">Offline</option><option value="unknown">Unknown</option></select></div><div class="col-md-4"><label class="form-label">Search Customer</label><input id="map-customer-search" class="form-control" placeholder="ID or label"></div></div><div id="network-map" style="height:620px;border-radius:.5rem"></div></div></div><script>document.addEventListener('livewire:navigated',()=>{if(!window.L){const s=document.createElement('script');s.src='https://unpkg.com/leaflet@1.9.4/dist/leaflet.js';document.head.appendChild(s);s.onload=()=>window.initNetworkMap?.();}else window.initNetworkMap?.();});window.initNetworkMap=()=>{const el=document.getElementById('network-map');if(!el||el._map)return;const map=L.map(el).setView([23.8103,90.4125],11);el._map=map;L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'&copy; OpenStreetMap contributors'}).addTo(map);const nodes=@json($nodes);const routerNodes=@json($routerNodes);const oltNodes=@json($oltNodes);let layers=[];let routerLayers=[];let oltLayers=[];const esc=v=>String(v||'').replace(/</g,'&lt;').replace(/>/g,'&gt;');const render=()=>{layers.forEach(x=>map.removeLayer(x));routerLayers.forEach(x=>map.removeLayer(x));oltLayers.forEach(x=>map.removeLayer(x));layers=[];routerLayers=[];oltLayers=[];const rf=document.getElementById('map-router-filter')?.value||'',sf=document.getElementById('map-status-filter')?.value||'',q=(document.getElementById('map-customer-search')?.value||'').toLowerCase().trim();const filtered=nodes.filter(n=>(!rf||n.router===rf)&&(!sf||n.status===sf)&&(!q||(String(n.id).toLowerCase().includes(q)||String(n.label||'').toLowerCase().includes(q))));routerNodes.forEach(r=>{const icon=L.divIcon({className:'network-router-marker',html:'🛜',iconSize:[28,28],iconAnchor:[14,14]});const m=L.marker([r.lat,r.lng],{icon}).bindPopup('<strong>MikroTik Router</strong><br>'+esc(r.name)+'<br>IP: '+esc(r.ip)+'<br>Location: '+esc(r.location||'—')+'<br>Status: '+esc(r.status)).addTo(map);routerLayers.push(m);});
oltNodes.forEach(o=>{const icon=L.divIcon({className:'network-olt-marker',html:'🔷',iconSize:[28,28],iconAnchor:[14,14]});const m=L.marker([o.lat,o.lng],{icon}).bindPopup('<strong>OLT</strong><br>'+esc(o.name)+'<br>IP: '+esc(o.ip)+'<br>Location: '+esc(o.location||'—')+'<br>Status: '+esc(o.status)).addTo(map);oltLayers.push(m);});
const rc={};filtered.forEach(n=>{const m=L.circleMarker([n.lat,n.lng],{radius:7}).bindPopup('<strong>Customer</strong><br>'+esc(n.label||n.id)+'<br>Router: '+esc(n.router||'Unassigned')+'<br>Status: '+esc(n.status)+'<br><a href="/customer?search='+encodeURIComponent(n.id)+'">View Customer</a>',{maxWidth:260}).addTo(map);layers.push(m);if(n.router)(rc[n.router]??=[]).push([n.lat,n.lng]);});Object.entries(rc).forEach(([router,pts])=>{const avg=pts.reduce((a,p)=>[a[0]+p[0],a[1]+p[1]],[0,0]).map(v=>v/pts.length);const marker=L.marker(avg).bindPopup('<strong>Router</strong><br>'+esc(router)+'<br>Customers: '+pts.length).addTo(map);routerLayers.push(marker);pts.forEach(p=>routerLayers.push(L.polyline([avg,p],{weight:2,opacity:.55}).addTo(map)));});const allPts=[...filtered.map(n=>[n.lat,n.lng]),...routerNodes.map(n=>[n.lat,n.lng]),...oltNodes.map(n=>[n.lat,n.lng])];if(allPts.length){map.fitBounds(L.latLngBounds(allPts),{padding:[30,30],maxZoom:15});}setTimeout(()=>map.invalidateSize(),100);};document.getElementById('map-router-filter')?.addEventListener('change',render);document.getElementById('map-status-filter')?.addEventListener('change',render);document.getElementById('map-customer-search')?.addEventListener('input',render);render();};</script><link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css"></div>